import pytest


def age_at(born: int, now: int) -> int:
    """Whole years elapsed from birth year `born` to current year `now`.

    Only years are given, so the result is simply `now - born`. The clock
    is never read; `now` is always supplied by the caller.

    Raises ValueError if `now < born`.
    """
    if now < born:
        raise ValueError(f"now ({now}) is before born ({born})")
    return now - born


def test_age_basic() -> None:
    assert age_at(2000, 2024) == 24
    assert age_at(1990, 2000) == 10


def test_age_same_year_is_zero() -> None:
    assert age_at(2024, 2024) == 0


def test_age_one_year() -> None:
    assert age_at(2023, 2024) == 1


def test_age_long_span() -> None:
    assert age_at(1900, 2024) == 124


def test_age_is_deterministic() -> None:
    # Depends only on its arguments, not on the clock.
    assert age_at(1980, 2020) == age_at(1980, 2020) == 40


def test_age_now_before_born_raises() -> None:
    with pytest.raises(ValueError):
        age_at(2025, 2024)


def test_age_far_future_birth_raises() -> None:
    with pytest.raises(ValueError):
        age_at(3000, 2000)
